// Generated lightweight metadata from batches b21-b29; no math task/model imports.
export const LESSONS = {"statwords":{"topicId":"mt_fmm-P17Vka","title":"几个“中间”，其实不同","formal":"平均数、中位数、众数与极差","summary":"总量均分、排序中间、最常出现，是不同的概括。极差是最大减最小的一个距离。数据一起变化不证明谁造成谁。","reflection":"一个数变大时，哪种“中间”会追着它走？","batch":"B21"},"meanbalance":{"topicId":"mt_Cg8VPguS_V","title":"高的分给低的，最后多高","formal":"平均数的均分意义与逆向求值","summary":"总量保持不变，均分给原来的份数。这个值不必是某一条原记录。已知平均数和份数，可以倒推总量与缺项。","reflection":"多加一份0，为什么不能当作什么也没发生？","batch":"B21"},"meandistance":{"topicId":"mt_ZfpeI1CFyP","title":"每个点离共同位置多远","formal":"平均绝对离差 MAD","summary":"先找到平均数，再把每个值到它的距离相加，连距离0也计入份数，最后再平均。MAD与原量单位相同；小一些表示围绕平均数更集中。","reflection":"左右的距离为什么不能互相抵消？","batch":"B21"},"averagestory":{"topicId":"mt_XSXnTQoQ4l","title":"一个平均数，够讲清楚吗","formal":"中心、极差与异常值","summary":"比较两组既看中心也看散开程度。极端值可能是真实的，要查背景，不能只因它不好看就删掉。","reflection":"两组平均一样，为什么体验可能完全不同？","batch":"B21"},"distributionlook":{"topicId":"mt_OwYms2tB1L","title":"一群点，藏着怎样的故事","formal":"分布的中心、离散、形态与异常","summary":"用同一把尺看中心、聚集、空隙、尾部与少数远点。图能显示现象，造成现象的原因还要额外证据。","reflection":"图里有两个小群，能直接知道为什么吗？","batch":"B21"},"quartiles":{"topicId":"mt_KCS9GbZgU_","title":"先排队，再看中间一半","formal":"四分位数与四分位距 IQR","summary":"本活动先排序；奇数个时整体中间值不重复放进上下半组，再分别找两半的中间。IQR是两个四分位位置之差；重复值处不能机械按闭区间数25%。","reflection":"把最大的一个搬远，中间一半一定跟着变吗？","batch":"B21"},"datasummary":{"topicId":"mt_tuEnyrp5Ia","title":"让别人知道你究竟看到了什么","formal":"带背景、中心与离散度的数据摘要","summary":"摘要要交代几份、量什么、怎样量、单位，以及中心和匹配的散开程度。平均数配MAD，中位数配IQR；长尾时后一组通常更稳健。","reflection":"只写“平均是14”，别人还缺哪些信息？","batch":"B21"},"digitalsets":{"topicId":"mt_mn765HbXi1","title":"两组放在一起，怎么比才公平","formal":"分类、等级与数值数据的数字比较","summary":"不同人数比较等级分布时用比例，等级顺序保持一致；名称类别没有高低。数值记录用共同数轴看众数、范围和形态。","reflection":"人数多的组，每类柱子都更高，就代表更喜欢吗？","batch":"B21"},"medialens":{"topicId":"mt_8IsaoMPvod","title":"这张图，有没有把你带偏","formal":"媒体统计图与结论审查","summary":"截掉柱图的零点会放大高度差的视觉比例。问过谁、多少人、怎么选，决定结论能说到哪里；改标题须保留这些限制。","reflection":"9个人喜欢，什么时候不能写“九成孩子喜欢”？","batch":"B21"},"fairdraw":{"topicId":"mt_4zgPzc6yu5","title":"问一部分人，怎么选这部分","formal":"总体、样本与简单随机抽样","summary":"总体是想了解的全体，样本是实际选到的部分。从完整名单随机抽，人人有机会；只问容易碰到的人会偏。随机也不保证每次样本恰好均衡。","reflection":"抽到了偏多的一组，能据此说抽签一定作弊吗？","batch":"B21"},"comparepeople":{"topicId":"mt_km4V6d5IAh","title":"样本不同，就能说整体不同吗","formal":"用随机样本比较两个总体","summary":"看差有多大，也看散开和抽样波动。抽样方法不公平时不能硬推整体；小于常见抽样波动的差，证据可能不够。","reflection":"差1分，而抽几次就能波动3分，够下结论吗？","batch":"B21"},"estimatepeople":{"topicId":"mt_fQ9Rw10fss","title":"从这一小份，估一大群","formal":"样本比例与样本均值的总体估计","summary":"样本比例乘总体人数得到估计人数，样本平均可估总体平均，但都不是精确清点。前提是对象和选法适合，便利或自愿样本可能不能推广。","reflection":"算出270，为什么还要写“大约”？","batch":"B21"},"comparegap":{"topicId":"mt_A2hKhHXgL5","title":"差得远不远，要用什么尺","formal":"用MAD刻画组间中心差与分布重叠","summary":"同一单位下，中心差可以除以MAD，说明相差约几个MAD。这个比值不能独自决定重叠，形态和朝向另一组的尾部也要看。","reflection":"平均位置差一样远，为什么两组还可能重叠得不一样？","batch":"B21"},"samplevary":{"topicId":"mt_x7V1qrkiqH","title":"再抽一次，为什么答案会变","formal":"抽样变异与样本量","summary":"每次从同一总体重新随机抽，估计会因抽到的人不同而变。这不是必然做错。较大随机样本通常更稳定，但不保证每次更准；个体差异与样本均值的差异也不同。","reflection":"五次结果的最小到最大，能保证罩住真实值吗？","batch":"B21"},"chanceorder":{"topicId":"mt_UcGn2hjhYU","title":"哪种机会更大","formal":"比较与排序可能性","summary":"比较时要看有利结果占全部等可能结果的多少。同样数量的红珠不代表相同机会；只比红珠个数可能看错。","reflection":"红珠更多，抽到红珠就一定更容易吗？","batch":"B22"},"chancefraction":{"topicId":"mt_-c4Ca_nBzX","title":"机会可以写成几分之几","formal":"概率的分数表示","summary":"等可能的每个结果都算在总数里，有利结果占全部结果的几分之几，就是事件概率。","reflection":"为什么分母不能只数没选中的那些？","batch":"B22"},"chancecalc":{"topicId":"mt_Zt30Gxi-qp","title":"把机会数清楚","formal":"简单概率计算","summary":"先核对每个结果是否等可能，再数有利结果与全部结果。等值分数描述同一个概率。","reflection":"有利的结果变多，机会会怎样？","batch":"B22"},"chanceline":{"topicId":"mt_t0g2SlP404","title":"机会放在哪里","formal":"0到1的概率刻度","summary":"0是不可能，1是一定，1/2、0.5和50%是同一位置。两种结果并不自动代表各占一半。","reflection":"什么时候“可能发生”和“一半机会”不是一回事？","batch":"B22"},"chancescale":{"topicId":"mt_vmQJAtAFuy","title":"每一份机会都一样吗","formal":"概率刻度与等可能条件","summary":"概率处于0和1之间。公平骰子的六个面等可能；不等大的转盘不能只因有两种颜色就各算一半。","reflection":"看见两种颜色，怎样知道各占多少机会？","batch":"B22"},"trialcompare":{"topicId":"mt_-bMnJcPJy8","title":"预想和实测会一样吗","formal":"实验频率与理论概率","summary":"理论模型给长期可能性的参考，每次实验会波动。更多独立重复通常使比例更稳定，不保证每次更接近。","reflection":"掷了很多次，次数一定刚好平均吗？","batch":"B22"},"trialestimate":{"topicId":"mt_sHJqh6UUya","title":"不知道规则，能先试出来吗","formal":"实验概率与相对频率","summary":"用实际发生次数除以试验总次数，得到对机会的估计。结果是有限试验的估计，不是确定的真实概率。","reflection":"为什么10次与100次的估计可能不同？","batch":"B22"},"chancemodel":{"topicId":"mt_aCwj2PCoRV","title":"用一个规则描述机会","formal":"概率模型","summary":"模型说明可能结果和各自机会。每个人等机会时才可按人数计数；观察到的比例可建立近似模型。异常结果支持进一步检查，不自动证明原因。","reflection":"观察和模型相差很大时，还需要查什么？","batch":"B22"},"chancesim":{"topicId":"mt_nzdtOLXWWa","title":"用数字替一次次尝试","formal":"随机事件模拟","summary":"用0—3代表一类、4—9代表另一类，十个数字等可能时对应40%。每次试到第一次成功为止；至少四次是前三次都未成功。","reflection":"两组模拟结果不一样，哪组一定错了？","batch":"B22"},"chancenone":{"topicId":"mt_3fwYu7imd4","title":"全部机会加起来是多少","formal":"完备互斥结果与概率和","summary":"把所有可能结果不重不漏地分开，概率合起来是1。事件和“不发生”恰好填满整体；重叠部分不能重复加。","reflection":"两个说法加起来等于1，就一定覆盖了全部结果吗？","batch":"B22"},"chancecomplement":{"topicId":"mt_XfyqXLqzpx","title":"没发生，又有多少机会","formal":"互补事件与重叠","summary":"某事件和它的补集不重不漏，概率和为1。两个普通事件可能重叠，合起来要把重叠部分只算一次。","reflection":"既是偶数又是质数的2，该算几次？","batch":"B22"},"chanceindependent":{"topicId":"mt_dlg6i-Lw0I","title":"上一次会改变下一次吗","formal":"独立与依赖事件","summary":"公平硬币前一次不会改变下一次概率；从袋中拿走而不放回会改变袋里剩下的比例。独立与能否同时发生是不同问题。","reflection":"不放回后，下一次还从原来的袋子里选吗？","batch":"B22"},"chancetree":{"topicId":"mt_GDtFU5fyUv","title":"两次选择会走出几条路","formal":"样本空间与概率树","summary":"按顺序列出每条路径；同一路径上乘机会，互不重叠的完整路径可以相加。不放回时第二层要按剩余物品重算。","reflection":"两个骰子的总和为什么不能当成等可能的11个结果？","batch":"B22"},"chancesets":{"topicId":"mt_1YwOCMMwD8","title":"一个东西可以属于两边吗","formal":"集合、并集、交集和补集","summary":"两边都有的放在重叠处，只算一次；两边都没有的仍在整个范围里。并集是至少一边，交集是两边都有。","reflection":"同时属于两边，为什么不该当成两个东西？","batch":"B22"},"chancevenn":{"topicId":"mt_eSv_w46u6H","title":"把两圈里的故事拼完整","formal":"韦恩图构造与计数","summary":"先确定两边都有的，再求各边独有和两边都没有；四个区域合起来等于整体。选人的概率以适当的整体作分母。","reflection":"只喜欢一种、两种都喜欢和两种都不喜欢，怎么不漏不重？","batch":"B22"},"shapehello":{"topicId":"mt_KJeEeTutJI","title":"转一转，还是它吗","formal":"平面图形的辨认","summary":"三角形由三条直边围成，圆没有直边和顶点。长方形有四个直角；正方形满足这些条件，还四边等长。大小、颜色和朝向不会改变这些性质。","reflection":"尖尖朝下，为什么还是三角形？","batch":"B23"},"shapeframe":{"topicId":"mt_2VR963szuk","title":"用点和线搭一个形状","formal":"图形的构造与立体框架","summary":"直边连接成闭合图形。正方体框架有8个顶点、12条棱、6个正方形面；屏幕上的框架是立体模型，不等于实物操作。","reflection":"只搭出一个正方形，为什么还不是一个盒子？","batch":"B23"},"shapepieces":{"topicId":"mt_XjwUlmxdCT","title":"小块能拼成什么","formal":"图形的组合","summary":"转动和移动平面小块，能组成新图形。拼好时小块既不重叠，也不在轮廓里留下空隙。","reflection":"相同的三角形转一转，能拼出什么？","batch":"B23"},"sidesfold":{"topicId":"mt_sBcRdUfAzV","title":"边数和折痕告诉了什么","formal":"边、顶点与轴对称","summary":"数边时每条只数一次。沿一条对称线反射后，图形与原来完全重合；面积一样不够。","reflection":"长方形对角线分成两半，折起来一定重合吗？","batch":"B23"},"shapemerge":{"topicId":"mt_MqqR7VUoz1","title":"一整个还可以拆成什么","formal":"平面图形的组合与分解","summary":"同一个图形可以由不同小块组成。半圆、四分之一圆指的是同一个圆被平均分开的部分。","reflection":"两块三角形拼好后，原来的接缝还在哪里？","batch":"B23"},"shapeidentity":{"topicId":"mt_bfhng6mOuy","title":"什么变了，名字不变","formal":"图形的定义性特征","summary":"三角形必须封闭且有三条直边；转动、放大、换颜色不会改变这一点。没有闭合的三条线不是三角形。","reflection":"一个图形看起来像，怎样检查它确实是？","batch":"B23"},"shapedraw":{"topicId":"mt_vJUa62bxeR","title":"画一画，再转过来","formal":"平面与立体图形的构造","summary":"平面多边形由互不交叉的直边围成；立体有面、棱和顶点。把立体转动，朝向改变但形状不变。","reflection":"只看一个角度，能看见立体的全部吗？","batch":"B23"},"shapesides":{"topicId":"mt_zuOGOGFAKb","title":"数清边，自己画出来","formal":"按边和顶点辨认多边形","summary":"五边形有五条直边和五个顶点；六边形有六条边和六个角。正的与不规则的五边形都是五边形。","reflection":"五条边长得不一样，还是五边形吗？","batch":"B23"},"shapeaxes":{"topicId":"mt_hRZyKvz1KN","title":"折过去，真的重合吗","formal":"轴对称与对称轴","summary":"反射后与原形完全重合的直线是对称轴。非正方形长方形有2条、正方形4条、正六边形6条；转动后对称轴也随之转动。","reflection":"一条线把面积平分，就一定是对称轴吗？","batch":"B23"},"quadsort":{"topicId":"mt_Xt1cRqaBOW","title":"一个图形能属于几家","formal":"四边形的包含关系","summary":"正方形有四个直角，因此也是长方形；它四边相等且对边平行，因此也是菱形和平行四边形。长方形未必四边相等。","reflection":"为什么正方形既能放进长方形，也能放进菱形？","batch":"B23"},"lineproperties":{"topicId":"mt_r8c43QB6wx","title":"两条边怎样相遇","formal":"平行与垂直","summary":"同一平面内不相交的直线平行；两条直线形成直角时垂直。一个图形可以同时具有平行和垂直的边。","reflection":"线段长短不同，还能平行吗？","batch":"B23"},"regularity":{"topicId":"mt_8H2kO4k2B9","title":"边一样长就够了吗","formal":"正多边形与不规则多边形","summary":"正多边形必须所有边相等、所有内角也相等。菱形边相等但角未必相等；非正方形长方形角相等但边未必全相等。","reflection":"只通过一项检查，能叫正多边形吗？","batch":"B23"},"shapemeasures":{"topicId":"mt_hdrMoiTgqu","title":"带着尺寸来画","formal":"指定长度和角度的图形构造","summary":"两边和夹角能确定一组三角形形状；长方形需四个直角，正五边形边和角都相等。屏幕生成的图形不评估真实尺子和量角器操作。","reflection":"闭合的三角形，尺寸就一定画对了吗？","batch":"B23"},"quadhierarchy":{"topicId":"mt_liIW336odh","title":"四边形的家族关系","formal":"平行四边形、长方形、菱形和正方形","summary":"正方形是长方形，也是菱形；长方形和菱形都是平行四边形。包含关系不能反过来说成每个长方形都是正方形。","reflection":"满足更多条件，是多了谁的身份？","batch":"B23"},"shapeuses":{"topicId":"mt_mN4Ye_vtR7","title":"为什么这个形状适合这里","formal":"立体形状与用途","summary":"圆柱有曲面和两个平面端，放倒可滚、立起便于叠放；长方体平面可对齐铺排。真实使用还要考虑材料、尺寸和其他条件。","reflection":"同一个物体换个摆法，能做的事会变化吗？","batch":"B23"},"shapeapprox":{"topicId":"mt_SK7WntVZ6y","title":"用熟悉的小形状画世界","formal":"用图形近似表示物体","summary":"复杂对象可用几个熟悉的平面或立体形状近似：房屋可以看作长方体加三棱柱屋顶。近似保留想强调的结构，不等同于实物。","reflection":"画出主要形状，哪些细节暂时可以不画？","batch":"B23"},"circleparts":{"topicId":"mt_xq3YHZ2zeR","title":"圆心到边缘有多远","formal":"圆心、半径、直径与周长","summary":"半径从圆心到圆上；直径经过圆心连接圆上两点，长度是半径的两倍。圆周是围绕圆的整条曲线。","reflection":"转一转直径，长度会变吗？","batch":"B23"},"geometrynotation":{"topicId":"mt_WtIFJSCQIT","title":"给图上的关系起名字","formal":"线段、角、平行与垂直的几何记号","summary":"线段可用两个端点命名；∠ABC的顶点在中间字母B。∥表示平行，⊥表示垂直。转动整个图形不改变关系。","reflection":"角的三个字母里，哪一个告诉我们顶点？","batch":"B23"},"compasswork":{"topicId":"mt_ZrsqGVG-Wt","title":"两段圆弧会在哪里相遇","formal":"圆规与直尺构造","summary":"以两端为圆心用相同半径画相交圆弧，交点到两端等距；连交点得到垂直平分线。相同方法可分角或作垂线。屏幕操作不等于实物尺规技巧。","reflection":"为什么换小一点的圆规，两段弧可能碰不到？","batch":"B23"},"placewords":{"topicId":"mt_qeZYF6HZ4o","title":"东西在哪里","formal":"相对位置与参照物","summary":"上、下、前、后、左、右都要说清参照物；前后和左右还与观察方向有关。","reflection":"换到另一边看，左边还是原来那边吗？","batch":"B24"},"turnwalk":{"topicId":"mt_TdV9YGJEoY","title":"先走，再转弯","formal":"方向、转动与直角","summary":"四分之一圈是90°，半圈是180°，四分之三圈是270°；顺时针与逆时针描述转动的方向。","reflection":"同样到左边，向左转一次和向右转三次有什么不同？","batch":"B24"},"pointbuild":{"topicId":"mt_i5_HnoFOYw","title":"点连起来，会出现什么","formal":"用坐标构造图形","summary":"先横向、再纵向确定点。连接点时还需看顺序；同一组点连成自交图形不等于闭合的长方形。","reflection":"少了一个角，能怎样找到它？","batch":"B24"},"pointmove":{"topicId":"mt_Uq5vYqboCR","title":"一起往哪里挪","formal":"坐标平移","summary":"平移时每个点都按同一个方向和距离移动；向右增加横坐标，向上增加纵坐标。","reflection":"一个角移动3格，其他角也必须移动3格吗？","batch":"B24"},"pointread":{"topicId":"mt_jBQS-CicNn","title":"给一个位置写地址","formal":"第一象限坐标","summary":"坐标是一对有顺序的数：先写从原点横向多少，再写纵向多少。图上交点表示位置。","reflection":"(2,4)和(4,2)为什么不是同一个地方？","batch":"B24"},"signedpoints":{"topicId":"mt_R4AY0LKxfl","title":"原点的另一边","formal":"四象限坐标","summary":"向左的横坐标为负，向下的纵坐标为负；坐标轴上的点不属于任何象限。","reflection":"向左3格、向上4格，要怎样写？","batch":"B24"},"pointaxes":{"topicId":"mt_oDlduFnemk","title":"两条数线交在一起","formal":"坐标轴与原点","summary":"横轴与纵轴是两条垂直数线，交点叫原点，写成(0,0)。横向数在前，纵向数在后。","reflection":"交换两个数，点会去哪里？","batch":"B24"},"pointdistance":{"topicId":"mt_h7zVgCDVmx","title":"隔着原点有多远","formal":"坐标距离与图形测量","summary":"水平或竖直的距离是坐标差的绝对值；跨过零时需数清两边。面积与周长使用不同单位。","reflection":"跨过原点时，为什么不能漏掉另一侧？","batch":"B24"},"pointstory":{"topicId":"mt_snlqRCiA1R","title":"点里的小故事","formal":"第一象限描点与数据含义","summary":"画点先找横坐标再找纵坐标；在真实或模拟数据图里，两轴的名称和单位决定点的含义。","reflection":"同一个(2,4)，换了轴的名字还在说同一件事吗？","batch":"B24"},"mirrorfold":{"topicId":"mt_hR2Y7NhMSY","title":"另一半藏在哪里","formal":"轴对称与对应点","summary":"镜像点在镜线两侧，到镜线的垂直距离相等。沿镜线反射后，对应部分应完全重合。","reflection":"两个点离镜线一样远，就一定是对应点吗？","batch":"B24"},"gridmotion":{"topicId":"mt_SH7QgFl8-v","title":"移动、翻面、转身","formal":"网格上的平移、反射和旋转","summary":"平移由方向和距离确定，反射由镜线确定，旋转由中心、角度和方向确定。它们保持长度和角度。","reflection":"同样到另一边，翻过去与转过去有什么不同？","batch":"B24"},"turnsym":{"topicId":"mt_NM5I3yN-Q6","title":"转过来，还能重合吗","formal":"旋转对称","summary":"绕指定中心转动，如果不足一整圈就能与原图重合，图形有旋转对称。数整圈内的重合位置时包含一整圈回到起点。","reflection":"同样转90°，为什么有的图形重合，有的不重合？","batch":"B24"},"flipandmove":{"topicId":"mt_efOeaGFyGM","title":"翻过来，再平移","formal":"反射、平移与全等","summary":"每个顶点都遵循同一条平移规则；镜像点到镜线的垂直距离相等。平移与反射保持边长和角度。","reflection":"位置变了，哪些长度和角还一样？","batch":"B24"},"geometrylab":{"topicId":"mt_RdfzwInyAj","title":"让图形自己动起来","formal":"动态几何中的变换与不变量","summary":"图形在软件里可平移、反射、绕中心旋转；比较对应边长与角度，能观察这些变换保持形状大小。","reflection":"变换先后换一换，结果一定一样吗？","batch":"B24"},"axisrules":{"topicId":"mt_lxaM6iVpdr","title":"镜子放在数线上","formal":"坐标平移与轴反射","summary":"平移对每个坐标加减相同数；关于横轴反射时横坐标不变、纵坐标反号，关于纵轴反射时则相反。","reflection":"关于横轴翻过去，为什么横向位置不变？","batch":"B24"},"gridchange":{"topicId":"mt_K0Y15w48SY","title":"斜着的镜子与转动中心","formal":"坐标变换","summary":"关于y=x反射时两个坐标交换；绕非原点旋转必须先看中心。平移、反射、旋转保持边长和角度。","reflection":"转动的中心换了，终点还会一样吗？","batch":"B24"},"patternfloor":{"topicId":"mt_61Nhj8W78f","title":"一块图形，能铺成什么","formal":"平面铺砌与变换图案","summary":"同样的正三角形、正方形或正六边形可各自铺满；正五边形不能单独形成这种正规铺砌。修改相对边并重复变换可产生新图案。","reflection":"有缝、重叠和刚好铺满，分别是什么样？","batch":"B24"},"growshape":{"topicId":"mt_y-BuQAfw4B","title":"放大时，什么一起变","formal":"相似、放大中心与比例","summary":"以指定中心放大时，各点到中心的距离乘相同倍数；对应边长成相同倍数，对应角不变。每条边都加同一个数一般不是放大。","reflection":"每条边都多5厘米，为什么不一定是同一个放大倍数？","batch":"B24"},"turnroute":{"topicId":"mt_Y9XKzLrUAZ","title":"走一步，还是转一下","formal":"方向与转动","summary":"前进或后退改变位置；转弯改变朝向。四分之一圈、半圈和一整圈描述转过的量。","reflection":"转了半圈，位置一定变了吗？","batch":"B25"},"anglecorner":{"topicId":"mt_8OAGVdeTJ_","title":"开口变了多少","formal":"角与转动","summary":"从同一个点出发的两条边之间的开口，可以用转过多少来描述。边画长或画短，不改变开口。","reflection":"两条边长一些，角一定更大吗？","batch":"B25"},"angleparts":{"topicId":"mt_3S10OOGPqu","title":"两条线在哪里相遇","formal":"角的顶点与射线","summary":"两条射线从同一个端点出发，形成角；共同端点叫顶点。角的大小由开口决定。","reflection":"门、剪刀与图形的角有什么共同点？","batch":"B25"},"rightcheck":{"topicId":"mt_MFfYcnv6Tv","title":"拿一个角作比较","formal":"直角与四分之一转","summary":"四分之一圈形成直角。两个直角是半圈，四个直角是一整圈。直角可以朝任意方向。","reflection":"边画得更长时，直角会变大吗？","batch":"B25"},"angletypes":{"topicId":"mt_h0CVtqI2xo","title":"哪个开口更大","formal":"锐角、直角与钝角","summary":"小于直角的角叫锐角；大于直角而小于平角的角叫钝角。比较时对齐顶点与一条边。","reflection":"怎样比较边长不同的两个开口？","batch":"B25"},"anglestraight":{"topicId":"mt_LBT-9jz7kR","title":"半圈与更多一点","formal":"平角、优角与周角","summary":"半圈是平角；超过半圈而不到一整圈是优角；一整圈是周角。两条边相同的位置仍要说清看哪一侧的开口。","reflection":"时针与分针之间为什么可以看出两个开口？","batch":"B25"},"degreeunit":{"topicId":"mt_qUGMyMYn9m","title":"一圈分成多少小份","formal":"度与一周","summary":"把一整圈等分成360份，每份对应一度。90度是四分之一圈，180度是半圈。","reflection":"45度相当于多少个一度？","batch":"B25"},"angleestimate":{"topicId":"mt_YUJ5pwalqL","title":"先看开口，再量一量","formal":"角度估计","summary":"先拿直角、半圈或四分之三圈作参照，估计开口，再测量检查。估计是接近，不必与测量完全相同。","reflection":"觉得比直角大一点时，量出50度合理吗？","batch":"B25"},"angleprotractor":{"topicId":"mt_4MFUAsbx_6","title":"让量角器对准","formal":"量角器的放置与刻度","summary":"量角器中心对准角的顶点，一条边与0度线对齐，再从对应的0度方向读另一条边。","reflection":"为什么两排刻度不能随便选一排？","batch":"B25"},"lineorientation":{"topicId":"mt_u23IGDxOpk","title":"两条线会相遇吗","formal":"平行线与垂线","summary":"同一平面内的平行线延长也不相交；垂线相交成直角。两种关系都与图形是否摆正无关。","reflection":"两条边长短不同，就不能平行吗？","batch":"B25"},"linemark":{"topicId":"mt_QysgF57dxh","title":"从一个点画出线","formal":"点、线段、射线与角","summary":"线段有两个端点；射线从一个端点沿一个方向延伸；平行和垂直描述两条线之间的关系。","reflection":"把一条边延长会改变角的开口吗？","batch":"B25"},"linenotation":{"topicId":"mt_e4V6hvcuEJ","title":"图上的小记号","formal":"几何图形中的标记","summary":"角名的三个字母中，中间字母是顶点；小方框表示直角。相同刻痕表示对应的长度相等。","reflection":"图上画得像一样长，没有刻痕就一定相等吗？","batch":"B25"},"angleadd":{"topicId":"mt_89riIKwGYp","title":"把开口分成几份","formal":"角度的可加性","summary":"一个开口分成互不重叠的几个部分，各部分的度数相加等于整个开口。","reflection":"知道整条直线是180度，怎样找缺的那一份？","batch":"B25"},"anglearound":{"topicId":"mt_oqziWKry-L","title":"一条直线，一整圈","formal":"直线和一点周围的角","summary":"一条直线的一侧是半圈180度；围绕一点一整圈是360度。对顶角相等，相邻角的关系要看它们是否合成直线。","reflection":"对面的角相等，挨着的角也是相等吗？","batch":"B25"},"anglecross":{"topicId":"mt_QDTO3GAgcq","title":"两根线交叉以后","formal":"对顶角与邻角","summary":"两条直线相交，对顶的两角相等；相邻并构成直线的两角合起来是180度。","reflection":"一边的角变大时，对面的角和旁边的角怎样变？","batch":"B25"},"rectanglefacts":{"topicId":"mt_KFKUR_gBg_","title":"长方形藏着的边和角","formal":"长方形的边角、周长与面积","summary":"长方形四个角都是直角，对边相等。周长是四边之和，面积是长乘宽；已知信息不同，找未知边的方法也不同。","reflection":"周长和面积都含有长和宽，为什么不能用同一个算法？","batch":"B25"},"anglechain":{"topicId":"mt_tedML_iu4Y","title":"一步接一步找角","formal":"连续使用角度关系","summary":"找到一个角后，可以用同一直线上的和或对顶角相等，继续找到其他角。每一步都要看清使用的关系。","reflection":"只知道一个角时，先找旁边还是对面的角？","batch":"B25"},"parallelangle":{"topicId":"mt_H_pNJ3ZI_S","title":"把一组角搬过去","formal":"平行线与截线所成的角","summary":"两条平行线被一条线穿过时，平移一组角可以比较对应位置；同位角和内错角相等，同旁内角合起来是180度。","reflection":"为什么平行线上的角并不全都相等？","batch":"B25"},"triangleangles":{"topicId":"mt_cdMlC7EpTJ","title":"三角形的角能拼成什么","formal":"三角形、多边形的内角和","summary":"三角形的三个内角合起来是180度；四边形可以分成两个三角形。正多边形的角相等时，才能把总和平均分。","reflection":"四边形里加一条线，能看到几个三角形？","batch":"B25"},"polygonangles":{"topicId":"mt_J03RFlVdas","title":"把多边形拆成三角形","formal":"多边形内角和与外角","summary":"从一个顶点把凸多边形拆成n−2个三角形，内角和是(n−2)×180度；正多边形的内角相等。","reflection":"六边形为什么能拆成四个三角形？","batch":"B25"},"shapefacts":{"topicId":"mt_DNYQLahbfa","title":"形状的条件会传下去","formal":"四边形与圆的性质","summary":"正方形同时具备长方形和菱形的条件；平行四边形的对边分别平行。直径是半径的两倍，圆周长是直径的π倍。","reflection":"正方形为什么能同时属于两个图形家族？","batch":"B25"},"triangledraw":{"topicId":"mt_Jf8xcX4UTq","title":"给出条件，画出三角形","formal":"按边角条件构造三角形","summary":"边长、角度和圆弧交点可以共同确定图形。画出后仍需测量和检查；屏幕上的输入绘图不等于实物尺规操作。","reflection":"两条圆弧相交时，交点为什么可以作为第三个顶点？","batch":"B25"},"trianglecongruent":{"topicId":"mt_167X6Ax8P7","title":"什么时候是同一块形状","formal":"三角形全等与对应","summary":"全等图形的对应边与对应角相等。三边、两边及夹角、两角及夹边等条件可以确定三角形；两边和非夹角不一定能。","reflection":"相同的两个边长和一个角，为什么有时还能画出两种形状？","batch":"B25"},"trianglepossible":{"topicId":"mt_4bc3EAxhlY","title":"这些条件能围出几个","formal":"三角形的存在与确定","summary":"三边必须任意两边和大于第三边；三个角相同只固定形状，不固定大小。两边与非夹角可能产生零个、一个或两个结果。","reflection":"交点落在底边上，为什么不能围成三角形？","batch":"B25"},"pythagoras":{"topicId":"mt_1VmTUxBrNd","title":"斜着走有多远","formal":"勾股定理与距离","summary":"只有在直角三角形中，直角对面的斜边所作正方形面积等于另外两个正方形面积之和。求斜边用平方后相加，求直角边从总面积减去已知面积，最后求平方根。","reflection":"为什么算出25之后，边长是5而不是25？","batch":"B26"},"trigbasics":{"topicId":"mt_KB_Czd7RQH","title":"一个角决定什么比例","formal":"直角三角形中的正弦、余弦与正切","summary":"斜边由直角确定；对边和邻边要相对所选锐角来认。相似直角三角形里，相同角对应的边长比例不变。sin是对边÷斜边，cos是邻边÷斜边，tan是对边÷邻边。","reflection":"换成另一个锐角看，哪些边的名字会交换？","batch":"B26"},"solidnames":{"topicId":"mt_Qcp2d_kuta","title":"转一转，认出它","formal":"常见立体图形","summary":"正方体、长方体、棱锥、球、圆柱和圆锥都是立体。球整个是弯曲的，圆柱有两个圆形平面，圆锥有一个圆形底面和一个尖点。生活物体可以近似这些形状。","reflection":"一个圆形的面，为什么不能代表整个圆柱？","batch":"B27"},"flatcorners":{"topicId":"mt_yGv8doDAmp","title":"边和角在哪里","formal":"平面图形与立体的特征","summary":"三角形有三条边、三个顶点；长方形有四条边、四个顶点。正方体有正方形的平面；图上的边和立体上两面相接的棱要分清。","reflection":"一个正方形和一个正方体，哪些地方相似？","batch":"B27"},"flatvsolid":{"topicId":"mt_mnEVZNkX3p","title":"平的和立起来的","formal":"二维图形与三维立体","summary":"理想的平面图形只有长度和宽度；立体还有厚度。圆是平面图形，球是立体；纸和硬币本身都有厚度，可以用来表示或近似图形。","reflection":"转到侧面时，圆和球看起来有什么不同？","batch":"B27"},"solidfaces":{"topicId":"mt_UooUHC_V7U","title":"立体上藏着什么形状","formal":"立体的平面与二维图形","summary":"圆柱和圆锥有圆形平面，四棱锥有三角形侧面，正方体有正方形面。一个面是立体的一部分，不能把整个立体叫做那个平面。","reflection":"同一个立体上的不同面，一定都是同一种形状吗？","batch":"B27"},"solidstack":{"topicId":"mt_QNxFnxikCN","title":"把立体叠成新东西","formal":"立体的组合与分解","summary":"几个立体可以组合成新的形状。看组合时可以从下往上找组成它的部分；屏幕上的拼搭是有限模型，不等于实际搭建能力。","reflection":"圆柱加圆锥之后，原来的两个部分还能找到吗？","batch":"B27"},"solidsort":{"topicId":"mt_fEuoBYw6bU","title":"按什么分在一起","formal":"按图形性质分类","summary":"同一组图形可以按不同性质分类：平面多边形可按边数分类；立体可按是否有曲面分类。说清分类依据，比只看颜色或大小更有用。","reflection":"同一个立体，换一条规则后会去哪里？","batch":"B27"},"solidpictures":{"topicId":"mt_wUSbRt3-qw","title":"一张图藏着什么立体","formal":"立体的平面表示","summary":"一张立体画和一张展开图，都能表示立体，但它们不是立体本身。可以检查各个面及其连接，想一想折起来或转过去会是什么。","reflection":"只看一张图，哪些面被挡住了？","batch":"B27"},"foldprism":{"topicId":"mt_REwgr0d_ss","title":"把纸片合成特别的盒子","formal":"三棱柱的展开图与立体结构","summary":"三棱柱有两个全等的三角形面和三个长方形面。展开图里的面沿边相连，合起来应完整围住立体，不能缺面或重叠。","reflection":"为什么两个三角形需要放在不同的端面？","batch":"B27"},"crossparts":{"topicId":"mt_nRksLqt-iR","title":"切开后看到什么","formal":"立体的面、棱、顶点与截面","summary":"三棱柱和四棱锥各有不同的面、棱和顶点。圆柱平行底面切开得到圆；本活动中圆锥过尖顶和底面中心的截面是三角形。","reflection":"换一个切的方向，看到的形状还会一样吗？","batch":"B27"},"prismslices":{"topicId":"mt_h02-C8PRrj","title":"换个位置切一刀","formal":"棱柱、棱锥和圆锥的平行截面","summary":"直棱柱平行于端面的截面与端面全等；本活动中的圆锥和四棱锥平行底面切开时，越靠近尖顶，截面越小。方向改变时不能直接套用这个比较。","reflection":"为什么同样移动切面，有的截面不变，有的会变小？","batch":"B27"},"compareheight":{"topicId":"mt_uhuxX8sg9f","title":"先从同一起点比","formal":"长度与高度的直接比较","summary":"比较长短或高矮时，先让一端或底部对齐，再看另一端。模型可以说明长、短、高、低，也可以比较两倍和一半。","reflection":"不把起点对齐，为什么容易看错？","batch":"B28"},"compareweight":{"topicId":"mt_-P1kdZhHbL","title":"大的就一定更重吗","formal":"质量的直接比较","summary":"外形大不一定重。天平两边放上物体后，较低的一边较重；平衡时两边相等。这里是模拟天平，不代替亲手掂量。","reflection":"看起来更大的物体为什么可能更轻？","batch":"B28"},"lengthstart":{"topicId":"mt_KaF0SQvaiu","title":"拿小块排一排","formal":"用统一单位测量长度","summary":"把一样长的单位从头到尾紧挨着摆，数量和单位一起说明长度；用尺时零刻度要对准起点。","reflection":"只说“用了六个”，为什么别人还不知道有多长？","batch":"B28"},"weightstart":{"topicId":"mt_zd0YkB3xNj","title":"用砝码找出多重","formal":"用天平与刻度表示质量","summary":"让物体与等量的砝码平衡，砝码的总量就是用这些单位表示的质量。记录时数字要带单位；屏幕模型不评实物操作。","reflection":"同一个物体换一套更小的砝码，块数会怎样？","batch":"B28"},"ordermeasure":{"topicId":"mt_BFJ-ch_8QU","title":"先量，再排顺序","formal":"比较和排列测量值","summary":"比较测量值要先确认量的类型和单位；单位不同先换成同一种。相等用等号，大小关系用大于或小于表示。","reflection":"50 cm 和 1 m，为什么不能只比50和1？","batch":"B28"},"indirectlength":{"topicId":"mt_skYly2Qm01","title":"不能挨着，怎么比","formal":"长度排序与间接比较","summary":"不能把物体放在一起时，可以用同一根纸条依次记下长度再比较。如果A比B长、B比C长，那么A比C长。","reflection":"同一根纸条为什么能帮两个不能碰面的物体比较？","batch":"B28"},"sameunitlength":{"topicId":"mt_cqSf213hSa","title":"单位要挨着排","formal":"相同单位的长度迭代","summary":"测量长度是数出多少个同样长的单位刚好铺满。单位之间不能留空或重叠，单位本身也不能一会儿大一会儿小。","reflection":"放了很多块，为什么也可能量得不对？","batch":"B28"},"lengthdifference":{"topicId":"mt_xWg0lI_gG4","title":"长多少，而不只是更长","formal":"长度差与单位","summary":"先用同一种单位量出两个长度，再用较长的减较短的，差也要带原来的长度单位。","reflection":"两件东西都加长2厘米，它们的长度差会变吗？","batch":"B28"},"estimateLength":{"topicId":"mt_OzRZ89GrQW","title":"先猜多长，再量","formal":"用参照物估计长度","summary":"先借助熟悉的单位作参照，再留下估计并测量；估计和测量值的差可以帮助调整下一次判断。","reflection":"一厘米的小段能怎样帮你估一整段？","batch":"B28"},"lengthtools":{"topicId":"mt_e4x3l2JeLI","title":"挑一件合适的工具","formal":"长度测量工具与零点","summary":"根据物体选择尺、米尺或卷尺；让零刻度对准起点，读另一端并写出单位。这里练习屏幕模型，真实工具仍需实际操作。","reflection":"尺子的边缘不是零刻度时，应该从哪里开始？","batch":"B28"},"twounits":{"topicId":"mt_jHv4BgRK8B","title":"同一段，换一把尺","formal":"同一长度的不同单位","summary":"同一段长度不因单位改变。单位较小时，通常需要更多个单位来铺满；厘米和英寸的数值不同，近似读数要标明“约”。","reflection":"同一张桌子，为什么可以同时说约10厘米和4英寸？","batch":"B28"},"precisionunits":{"topicId":"mt_e7tLi9SCIE","title":"小单位能看清多少","formal":"单位大小与测量分辨率","summary":"同一个量用较小的均匀单位时，数量通常更多，剩下未量清的部分也可能更小。对齐、工具和读数同样影响结果，小单位不保证绝对准确。","reflection":"为什么两支铅笔还剩一点，换小回形针更容易说清？","batch":"B28"},"readscales":{"topicId":"mt_SOM6Imm2sO","title":"两条刻度之间是多少","formal":"仪器刻度与数字读数","summary":"先看相邻标出的数字差多少，再判断中间位置；读数必须带单位。数字秒表的分和秒不能只看成同一个整数。","reflection":"400和600正中间为什么是500？","batch":"B28"},"baseconversions":{"topicId":"mt_d8al9JcajP","title":"换单位，量没变","formal":"长度与时间单位换算","summary":"同一个量可以用不同单位表示：1 km是1000 m，1小时是60分钟，1周是7天。换成较小单位通常需要更多个单位。","reflection":"3千米和3000米，是两段不同的路吗？","batch":"B28"},"metricconversions":{"topicId":"mt_Zks8xyInSG","title":"把大单位拆成小单位","formal":"公制单位及复名数换算","summary":"千米、米、厘米、毫米，以及千克与克、升与毫升各有固定关系。复名数先换成同单位，再合起来。","reflection":"2千克350克为什么是2350克，不是235克？","batch":"B28"},"imperialconversions":{"topicId":"mt_p6MhZJYYPN","title":"不同单位怎样大约对应","formal":"公制与英制近似换算","summary":"这里用1英寸约2.5厘米、1千克约2.2磅、1升约1.75英制品脱作估计；1英寸实际恰好2.54厘米。英制品脱与美制液体品脱不同。","reflection":"为什么用约等号，不能把估计当成精确值？","batch":"B28"},"decimalunits":{"topicId":"mt_2VpdPjvewx","title":"小数也能换单位","formal":"用小数表示单位换算","summary":"换单位是把同一个量重新计数。3250克是3.25千克，0.45千米是450米；不要只机械地添零。","reflection":"换单位时，小数点移动的原因是什么？","batch":"B28"},"unitstories":{"topicId":"mt_SqhXQhAEUf","title":"先统一，再算下去","formal":"多步骤测量问题","summary":"有多个步骤时，先明确每个量与单位，再选择相乘、换算或比较。比较2.5升和2450毫升时，要先换成相同单位。","reflection":"数字大的一定代表装得更多吗？","batch":"B28"},"mileskm":{"topicId":"mt_3tPI0HqqcN","title":"英里和千米怎么比","formal":"英里与千米的近似换算","summary":"用5英里约等于8千米作估计，1英里约1.6千米。数量翻倍，两种表示一起翻倍；实际英里到千米的精确关系略有不同。","reflection":"为什么10英里约16千米，而不是只在10上加3？","batch":"B28"},"measureplot":{"topicId":"mt_mayItsxMUu","title":"量完，把记录排上图","formal":"整数测量与点图","summary":"逐个测量并按要求取整，再在均匀刻度上为每条记录放一个点。某个位置没有记录，也不能把那个刻度挤掉。","reflection":"最高的一堆点表示最长，还是出现次数最多？","batch":"B28"},"quarterplot":{"topicId":"mt_ghK1mnEstc","title":"半格和四分之一格","formal":"半、四分之一单位的测量点图","summary":"先看每个完整单位被平均分成几段，再把长度取到最近的半或四分之一单位。数轴要等距，一条记录对应一个点。","reflection":"2¼、2½和2¾在尺上为什么要等间隔？","batch":"B28"},"eighthplot":{"topicId":"mt_42QD6nYjiZ","title":"八分之一格的记录","formal":"分数单位点图与加减","summary":"每条测量记录在对应刻度放一个点；最长减最短得到差。求总长度时，要把每条长度相加，不能只数点的个数。","reflection":"两条都是2¼，求总长时要加几次2¼？","batch":"B28"},"lengthstory":{"topicId":"mt_DLcEzmmj2r","title":"哪一段还不知道","formal":"长度情境中的部分、整体与未知数","summary":"先把一整段和已知的一段摆出来。未知的可能是剩下的一段，也可能是原来较短的那一段；用 □ 表示未知量，同一个关系可以从加法或减法记录。","reflection":"故事里出现“更长”，为什么有时要减才能找到较短的那一段？","batch":"B29"},"measurecalc":{"topicId":"mt_6oxQPNLHNv","title":"量出来，再接起来","formal":"同单位测量与加减","summary":"先对齐尺的零刻度，或让天平两边平衡；记录数值和单位。合起来与相差多少是不同的问题，算之前要确认各段使用同样大小的单位。","reflection":"250 mL 和 400 mL 合起来时，650 后面为什么要保留 mL？","batch":"B29"},"practicalmeasure":{"topicId":"mt_5HV4mbgSGH","title":"分一分，时间往前走","formal":"小数、分数与测量情境","summary":"2.5 kg 是 2500 g，分成四份，每份 625 g，也就是 0.625 kg。时间按 60 分钟进一小时；小数长度相接时保持同一个单位。","reflection":"一小时四十五分钟，为什么不能直接写成 1.45 小时？","batch":"B29"},"temperaturechange":{"topicId":"mt_RVK655t391","title":"从零这边走到另一边","formal":"有向数量与跨零间隔","summary":"零是标尺上的一个位置，不是额外的一步。从 3℃ 到 −5℃，先走 3 度到零，再走 5 度到终点，共相差 8 度；距离是非负的。","reflection":"从 3 到 −5，为什么相差 8，而不是 5−3？","batch":"B29"}};
